-- Set programs that you use
-- Opened in a marker cwd so ~/.bashrc can run fetchit for a new window
-- but not for a split. +new-window talks to the running instance; the
-- fallback covers the case where no Ghostty is running yet.
local ghostty_new_window_dir = "$HOME/.local/state/ghostty/new-window"
local terminal    = "ghostty +new-window --working-directory=" .. ghostty_new_window_dir
                 .. " || ghostty --working-directory=" .. ghostty_new_window_dir
local fileManager = "dolphin"
local menu        = "hyprlauncher"
local browser     = "firefox"
-- The shell's own launcher, not rofi. `qs ipc` talks to the running
-- instance, so this costs no process spawn and the window is styled by the
-- same tokens as the bar.
local app_launcher = "qs ipc -c rd-shell call launcher toggle"


