---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
-- hl.on("hyprland.start", function () 
--   hl.exec_cmd(terminal)
--   hl.exec_cmd("nm-applet")
--   hl.exec_cmd("waybar & hyprpaper & firefox")
-- end)

hl.on("hyprland.start", function ()
    -- Not swaybg directly any more: the wallpaper switcher (CTRL+ALT+F) writes
    -- whatever you picked to ~/.cache/rd-shell/wallpaper, and --restore puts that
    -- back up and re-runs matugen so the bar comes back the right colour too. It
    -- falls back to rd.png when nothing has been picked yet, so a fresh machine
    -- boots to the same wallpaper this line used to name.
    hl.exec_cmd("~/.config/quickshell/rd-shell/scripts/wallpaper-apply.sh --restore")
    -- The window rules near the bottom pin these to their workspaces on the
    -- second monitor, silently, so booting does not steal focus.
    hl.exec_cmd("vesktop")
    hl.exec_cmd("flatpak run com.spotify.Client")
    hl.exec_cmd("flatpak run org.signal.Signal")
    hl.exec_cmd("tuned-adm profile throughput-performance")
    hl.exec_cmd("wayvibes ~/Documents/Soundpacks/nk-cream -v 2 --mouse ~/Documents/Soundpacks/mp_corsair/ --mouse-volume 0.5 --background")
    hl.exec_cmd("~/.config/quickshell/rd-shell/launch.sh")
    hl.exec_cmd("hyprctl setcursor Bibata-Original-Classic 36")
    -- `hyprpm enable` only marks a plugin as wanted; nothing loads it into a
    -- fresh session but this. Loading one re-parses this file, which is what
    -- lets the plugin_loaded("hyprexpo") block below apply its options.
    hl.exec_cmd("hyprpm reload -n")
end)

