-- Refer to https://wiki.hypr.land/Configuring/Basics/Variables/
hl.config({
    general = {
        gaps_in  = 5,
        gaps_out = 0,

        border_size = 2,

        col = {
            active_border   = { colors = {"rgb(b86e38)"}, angle = 45 },
            inactive_border = "rgba(595959aa)",
        },

        -- Set to true to enable resizing windows by clicking and dragging on borders and gaps
        resize_on_border = false,

        -- Please see https://wiki.hypr.land/Configuring/Advanced-and-Cool/Tearing/ before you turn this on
        allow_tearing = false,

        layout = "dwindle",
    },

    -- Grouped windows (tabbed with a group bar) in the palette rather than
    -- Hyprland's yellow defaults. Static caelus values here, the same ones as
    -- the borders above; scripts/wallpaper-apply.sh swaps both for the
    -- matugen colours on every wallpaper switch, in the same eval.
    group = {
        col = {
            border_active   = { colors = {"rgb(b86e38)"}, angle = 45 },
            border_inactive = "rgba(595959aa)",
        },
        groupbar = {
            col = {
                active   = "rgb(b86e38)",
                inactive = "rgba(595959aa)",
            },
        },
    },

    decoration = {
        -- A 4px radius with a plain circular arc (power 2 is a circle, 4 a
        -- squircle): just enough to soften the corners against the bar's
        -- rounded islands without turning tiles into cards.
        rounding       = 4,
        rounding_power = 2,

        -- Forced on every window, whether or not the app has a transparency
        -- setting of its own -- which also means it makes the *contents*
        -- translucent, text included, not just the background the way an
        -- app-side option would. Blur below is what keeps that readable.
        active_opacity   = 0.85,
        inactive_opacity = 0.85,

        -- A fullscreen window has nothing behind it worth seeing, and the
        -- blur would only be sampling black. This is also Hyprland's own
        -- default -- stated here so the two above can be changed without
        -- having to remember that it exists.
        fullscreen_opacity = 1.0,

        -- Dims every unfocused window, so the active one reads as active on
        -- sight instead of only by the border colour above.
        dim_inactive = true,
        dim_strength = 0.25,

        shadow = {
            enabled      = true,
            range        = 4,
            render_power = 3,
            color        = 0xee1a1a1a,
        },

        -- Blurs whatever shows through the window opacity set above.
        -- Deliberately a step gentler than the lock screen (hyprlock.conf is
        -- 2 passes at size 8): same passes, smaller radius.
        blur = {
            enabled   = true,
            size      = 6,
            passes    = 2,
            vibrancy  = 0.1696,

            -- Without xray, the bar's own blur (see the quickshell-blur layer
            -- rule below) samples whatever window is directly behind it, so
            -- maximising a window smears its content straight up into the bar.
            -- xray makes it blur past windows to the desktop/wallpaper layer
            -- instead, the same thing xray does for any other blurred layer.
            -- Off. xray makes a blurred layer sample the desktop instead of
            -- the windows under it, which is the textbook setting for a bar
            -- -- and it looks wrong here. The islands are 28% opaque, so with
            -- xray they carry the wallpaper's brightness rather than the
            -- window's, and on a light wallpaper the bar washes out and the
            -- text stops being readable against it. The bar picking up
            -- whatever is actually beneath it is the better-behaved default
            -- on this setup.
            xray = false,
        },
    },

    animations = {
        enabled = true,
    },
})

-- Reapplies the dynamic-colour window border after every parse. The
-- general.col literals just above are set unconditionally every time this
-- file runs, which is what silently reverts a wallpaper-driven border back
-- to the static caelus orange on every `hyprctl reload` -- hyprpm's own
-- reload included. Hyprland's `exec` (unlike `exec-once`, which is what the
-- hl.on("hyprland.start", ...) block below amounts to -- it only fires once,
-- not on every reload) runs on every parse too, so this line, placed right
-- after the literals above, puts the live colour straight back. Safe when
-- dynamic colour is off: the script's --border branch just re-applies these
-- same literals in that case, so this is a no-op either way for a machine
-- that has never touched the wallpaper switcher.
hl.exec_cmd("~/.config/quickshell/rd-shell/scripts/wallpaper-apply.sh --border")

