-- Workspace overview grid, from the hyprexpo plugin:
-- https://github.com/sandwichfarm/hyprexpo (a maintained fork -- upstream
-- hyprwm/hyprland-plugins dropped hyprexpo in 2026-05). Installed with
-- `hyprpm add https://github.com/sandwichfarm/hyprexpo && hyprpm enable
-- hyprexpo`, never bundled with Hyprland, so this must do nothing on a
-- machine that has not run that command.
--
-- hl.config has no dedicated field for plugin settings -- there is no
-- `HL.ConfigOpt.plugin` in the Lua stub -- but it does take a `plugin` key
-- at the top of the table and validate the dotted path underneath it
-- against whatever is currently registered. Confirmed with `hyprctl eval`:
-- before hyprexpo was loaded, `hl.config({ plugin = { hyprexpo = { columns
-- = 3 } } })` failed with "unknown config key 'plugin.hyprexpo.columns'" --
-- the same error a typo'd *core* key gets (tried general.made_up_key_xyz,
-- same shape of error), so this is generic path validation against the live
-- config registry, not a special case that rejects "plugin" outright. That
-- error also does NOT stop the rest of the file from running -- a bind
-- placed right after it in the same eval still registered -- so an
-- unguarded call would have been survivable, just noisy (a config-error
-- toast on every reload until the plugin is installed). The plugin_loaded
-- guard below avoids that noise rather than avoiding a crash.
local function plugin_loaded(name)
    for _, p in ipairs(hl.get_loaded_plugins()) do
        if p.name == name then return true end
    end
    return false
end

if plugin_loaded("hyprexpo") then
    -- Real option names for this fork, enumerated with `hyprctl getoption
    -- plugin:hyprexpo:<name>` against the loaded plugin rather than trusted
    -- from its README (which still lists an `overview_mode` key this build
    -- reports back as "no such option"). All six below came back with a
    -- live default, confirming the name and that hl.config accepts it.
    hl.config({
        plugin = {
            hyprexpo = {
                columns               = 3,
                gaps_in               = 5,   -- matches general.gaps_in above
                gaps_out              = 0,   -- matches general.gaps_out above
                workspace_method      = "center current",
                border_color_current  = "rgb(b86e38)", -- this file's active_border colour;
                                                        -- dropped the 45deg angle, meaningless
                                                        -- on a single flat tile border
                gesture_fingers       = 0,   -- no touchpad device configured in this file;
                                              -- this fork replaced the old enable_gesture
                                              -- bool with a finger count, 0 = off (default)
            },
        },
    })
end

