local mainMod = "SUPER" -- Sets "Windows" key as main modifier

-- Example binds, see https://wiki.hypr.land/Configuring/Basics/Binds/ for more
--
-- Every bind carries a description. SUPER+K lists them (the shell's keybind
-- overview), and it reads them out of `hyprctl binds` — where a Lua bind's dispatcher is the opaque
-- "__lua", so the description is the only thing that can say what it does.
hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd(terminal), { description = "Terminal (ghostty)" })
local closeWindowBind = hl.bind(mainMod .. " + W", hl.dsp.window.close(), { description = "Close window" })
-- closeWindowBind:set_enabled(false)
hl.bind(mainMod .. " + M", hl.dsp.exec_cmd("qs ipc -c rd-shell call power toggle"), { description = "Power menu" })
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd("hyprlock"), { description = "Lock the session" })
hl.bind(mainMod .. " + N", hl.dsp.exec_cmd("qs ipc -c rd-shell call notifications toggle"), { description = "Notification panel" })
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager), { description = "File manager (dolphin)" })
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }), { description = "Float / tile window" })
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd(menu), { description = "Launcher (hyprlauncher)" })
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo(), { description = "Pseudotile window" })
-- Real fullscreen (covers the bar, no gaps). internal = 2 fullscreens the window,
-- client = 0 hides that fact from the app, so Firefox/Chromium keep their tab bar
-- instead of dropping into their own presentation mode.
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen_state({ action = "toggle", internal = 2, client = 0 }), { description = "Fullscreen window" })
-- Fake fullscreen: the window is the only thing on the workspace, but it stops
-- at the bar instead of swallowing it. internal = 1 is Hyprland's maximize,
-- which fills the monitor minus the reserved area the bar already claims --
-- so it lands exactly where a maximized window would, while still hiding
-- everything else the way a real fullscreen does. client = 0 for the same
-- reason as above: the app is never told, so nothing switches itself into a
-- presentation mode over it.
hl.bind(mainMod .. " + SHIFT + F", hl.dsp.window.fullscreen_state({ action = "toggle", internal = 1, client = 0 }), { description = "Fake fullscreen (keeps the bar)" })
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"), { description = "Toggle split direction" })    -- dwindle only
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd(browser), { description = "Browser (firefox)" })
hl.bind(mainMod .. " + SPACE", hl.dsp.exec_cmd(app_launcher), { description = "App launcher" })
-- This cheat sheet. The script reads the descriptions above back out of
-- `hyprctl binds`, so a new bind shows up in it as soon as it is described.
-- The same list inside the bar, with a search field (KeybindOverview.qml).
hl.bind(mainMod .. " + K", hl.dsp.exec_cmd("qs ipc -c rd-shell call keybinds toggle"), { description = "Keybind overview (search)" })
-- The system monitor popup, on the key every other desktop opens its task
-- manager with.
hl.bind("CTRL + SHIFT + ESCAPE", hl.dsp.exec_cmd("qs ipc -c rd-shell call system toggle"), { description = "System monitor" })
hl.bind("CTRL + SHIFT + M", hl.dsp.exec_cmd("~/.config/hypr/scripts/mic-toggle.sh"), { description = "Mute / unmute the microphone" })
-- Cycle the keyboard layout (us <-> de). "all" keeps every keyboard on the same
-- layout; switching only the main one leaves the others behind. Hyprland emits
-- activelayout on the event socket, which the bar listens to.
hl.bind("CTRL + SHIFT + SPACE", hl.dsp.exec_cmd("hyprctl switchxkblayout all next"), { description = "Cycle the keyboard layout" })

-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "left" }),  { description = "Focus left" })
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "right" }), { description = "Focus right" })
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "up" }),    { description = "Focus up" })
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "down" }),  { description = "Focus down" })

-- Move active window with mainMod + SHIFT + arrow keys.
-- movewindow only swaps with a window that already sits in that direction, so on
-- a plain side-by-side pair up/down are dead keys. When the pressed axis is empty
-- but the other one is not, flip the dwindle split first: the pair restacks along
-- the pressed axis, each window stretched across the full width (or height), and
-- the move then lands in the freed slot.
local function corners(w)
    local at, size = w.at, w.size
    if type(at) ~= "table" or type(size) ~= "table" then return nil end
    return at.x, at.y, at.x + size.x, at.y + size.y
end

local function has_neighbour(w, direction)
    local ws = w.workspace
    if not ws then return false end
    local x1, y1, x2, y2 = corners(w)
    if not x1 then return false end

    for _, other in ipairs(ws:get_windows()) do
        if other.address ~= w.address and other.mapped and not other.hidden and not other.floating then
            local ox1, oy1, ox2, oy2 = corners(other)
            if ox1 then
                local overlaps_x = ox1 < x2 and ox2 > x1
                local overlaps_y = oy1 < y2 and oy2 > y1
                if direction == "left"  and overlaps_y and ox2 <= x1 then return true end
                if direction == "right" and overlaps_y and ox1 >= x2 then return true end
                if direction == "up"    and overlaps_x and oy2 <= y1 then return true end
                if direction == "down"  and overlaps_x and oy1 >= y2 then return true end
            end
        end
    end
    return false
end

local PERPENDICULAR = {
    left  = { "up", "down" },
    right = { "up", "down" },
    up    = { "left", "right" },
    down  = { "left", "right" },
}

local OPPOSITE = { left = "right", right = "left", up = "down", down = "up" }

local function move_window(direction)
    return function()
        local window = hl.get_active_window()
        local move   = hl.dsp.window.move({ direction = direction })
        if not window or window.floating or window.fullscreen ~= 0
            or has_neighbour(window, direction) then
            hl.dispatch(move)
            return
        end

        local perpendicular = PERPENDICULAR[direction]
        if has_neighbour(window, perpendicular[1]) or has_neighbour(window, perpendicular[2]) then
            hl.dispatch(hl.dsp.layout("togglesplit"))
            local flipped = hl.get_active_window()
            if flipped and has_neighbour(flipped, direction) then
                hl.dispatch(move)
            end
        elseif has_neighbour(window, OPPOSITE[direction]) then
            -- Last window of the row or column: swap back along the axis instead
            -- of letting movewindow hand it to the monitor next door.
            hl.dispatch(hl.dsp.window.move({ direction = OPPOSITE[direction] }))
        end
        -- Otherwise it is the only tiled window, so the press does nothing.
    end
end

hl.bind(mainMod .. " + SHIFT + left",  move_window("left"),  { description = "Move window left" })
hl.bind(mainMod .. " + SHIFT + right", move_window("right"), { description = "Move window right" })
hl.bind(mainMod .. " + SHIFT + up",    move_window("up"),    { description = "Move window up" })
hl.bind(mainMod .. " + SHIFT + down",  move_window("down"),  { description = "Move window down" })
hl.bind("CTRL + ALT + up", hl.dsp.exec_cmd("~/.config/hypr/scripts/screenshot.sh area"), { description = "Screenshot a region" })
hl.bind("CTRL + ALT + F", hl.dsp.exec_cmd("qs ipc -c rd-shell call wallpaper toggle"), { description = "Wallpaper switcher" })

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
local MAIN, SECOND = "DP-1", "DP-2"
-- The second monitor owns the workspaces after the main monitor's six, so its
-- Nth workspace is SECOND_WS_BASE + N.
local SECOND_WS_BASE = 6

for i = 1, 6 do
    hl.workspace_rule({
        workspace  = tostring(i),
        monitor    = MAIN,
        default    = (i == 1),
        persistent = true,
    })
    hl.bind(mainMod .. " + " .. i,         hl.dsp.focus({ workspace = i }),      { description = "Workspace " .. i })
    hl.bind(mainMod .. " + SHIFT + " .. i, hl.dsp.window.move({ workspace = i }), { description = "Move window to workspace " .. i })
end

for j = 1, 4 do
    local ws = SECOND_WS_BASE + j
    hl.workspace_rule({
        workspace  = tostring(ws),
        monitor    = SECOND,
        default    = (j == 1),
        persistent = true,
    })
    hl.bind("CTRL + " .. j,         hl.dsp.focus({ workspace = ws }),      { description = "Workspace " .. ws .. " (second monitor)" })
    hl.bind("CTRL + SHIFT + " .. j, hl.dsp.window.move({ workspace = ws }), { description = "Move window to workspace " .. ws })
end

-- Spotify lives on the third workspace of the second monitor. The window rule
-- near the bottom of this file pins a newly opened window there, so this bind
-- only has to pick between focusing the running client and starting one.
local SPOTIFY_WS = SECOND_WS_BASE + 3
local SIGNAL_WS  = SECOND_WS_BASE + 2
local VESKTOP_WS = SECOND_WS_BASE + 1
hl.bind("CTRL + ALT + S", function()
    if hl.get_window("class:spotify") then
        hl.dispatch(hl.dsp.focus({ window = "class:spotify" }))
    else
        -- Switch first so the workspace is in view while the client starts.
        hl.dispatch(hl.dsp.focus({ workspace = SPOTIFY_WS }))
        hl.dispatch(hl.dsp.exec_cmd("flatpak run com.spotify.Client"))
    end
end, { description = "Spotify on workspace " .. SPOTIFY_WS .. " (second monitor)" })

-- Vesktop lives on the first workspace of the second monitor, same shape as the
-- Spotify bind above: focus the running client, or switch and start one.
hl.bind("CTRL + ALT + V", function()
    if hl.get_window("class:vesktop") then
        hl.dispatch(hl.dsp.focus({ window = "class:vesktop" }))
    else
        hl.dispatch(hl.dsp.focus({ workspace = VESKTOP_WS }))
        hl.dispatch(hl.dsp.exec_cmd("vesktop"))
    end
end, { description = "Vesktop on workspace " .. VESKTOP_WS .. " (second monitor)" })

-- Signal sits on the second workspace of the second monitor.
hl.bind("CTRL + ALT + A", function()
    if hl.get_window("class:org.signal.Signal") then
        hl.dispatch(hl.dsp.focus({ window = "class:org.signal.Signal" }))
    else
        hl.dispatch(hl.dsp.focus({ workspace = SIGNAL_WS }))
        hl.dispatch(hl.dsp.exec_cmd("flatpak run org.signal.Signal"))
    end
end, { description = "Signal on workspace " .. SIGNAL_WS .. " (second monitor)" })

-- Workspace overview (hyprexpo plugin, see the plugin config block above).
-- grave (SUPER + `) was unused in this file and is the upstream default for
-- this plugin's toggle. Under the Lua config the plugin exposes its toggle as
-- hl.plugin.hyprexpo.expo; the legacy `hl.dsp.exec_raw("hyprexpo:expo",
-- "toggle")` still answers "ok" but draws nothing (checked with a screenshot
-- either side), while the Lua call opens the grid. Looked up at press time,
-- not bind time, because this file is parsed once before `hyprpm reload`
-- has loaded the plugin; the guard keeps the key a silent no-op without it.
hl.bind(mainMod .. " + grave", function()
    local expo = hl.plugin and hl.plugin.hyprexpo
    if expo then expo.expo("toggle") end
end, { description = "Workspace overview (hyprexpo)" })

-- The scratchpad special workspace (SUPER+S toggled it, SUPER+SHIFT+S moved a
-- window into it) went unused, so SUPER+SHIFT+S now builds the r/unixporn
-- showcase layout instead.
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.exec_cmd("~/.config/quickshell/rd-shell/scripts/showcase.sh"), { description = "Showcase layout (fetchit/btop/cava/yazi)" })

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }), { description = "Next workspace" })
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }), { description = "Previous workspace" })

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true, description = "Move window (drag)" })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true, description = "Resize window (drag)" })

-- Laptop multimedia keys for volume and LCD brightness
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true, description = "Volume up" })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true, description = "Volume down" })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true, repeating = true, description = "Mute / unmute" })
hl.bind("XF86AudioMicMute",     hl.dsp.exec_cmd("~/.config/hypr/scripts/mic-toggle.sh"),   { locked = true, repeating = true, description = "Mute / unmute the microphone" })
hl.bind("XF86MonBrightnessUp",  hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%+"),                  { locked = true, repeating = true, description = "Brightness up" })
hl.bind("XF86MonBrightnessDown",hl.dsp.exec_cmd("brightnessctl -e4 -n2 set 5%-"),                  { locked = true, repeating = true, description = "Brightness down" })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true, description = "Next track" })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true, description = "Play / pause" })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true, description = "Play / pause" })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true, description = "Previous track" })


