-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- Floats are small, one-off panels (pickers, confirms, hyprland-run), not
-- docked tiles, so they can afford to arrive differently. A window rule takes
-- `animation` -- the style, not a full "speed bezier style" string; the speed
-- and curve stay with the global `windows` leaf. Floats grow from 85% instead
-- of the global popin, which reads as the panel appearing where you asked for
-- it rather than sliding in from the layout.
hl.window_rule({
    name  = "float-popin",
    match = { float = true },

    animation = "popin 85%",
})

-- dim_inactive is for telling tiles apart; a fullscreen window is the only
-- thing on its monitor, so there is nothing to tell it apart from -- dimming
-- it only darkens a video left playing on the other screen.
hl.window_rule({
    name  = "fullscreen-no-dim",
    match = { fullscreen = true },

    no_dim = true,
})

-- The bar. Its three islands are 80% opaque and the gaps between them are
-- fully transparent, so `ignore_alpha` at 0.2 blurs the plates and leaves the
-- gaps alone -- without it the whole 44px strip would be blurred, including
-- the wallpaper showing through above and below the islands. `blur_popups`
-- covers the cards the bar hangs under its pills. The wallpaper sits on its
-- own `qs-wallpaper` layer and must never match this, hence the anchored
-- pattern rather than a prefix.
hl.layer_rule({
    name  = "quickshell-blur",
    match = { namespace = "^quickshell$" },

    blur         = true,
    blur_popups  = true,
    ignore_alpha = 0.2,
})

-- The OSDs -- volume, microphone, brightness, keyboard layout. Each is its own
-- layer surface with its own namespace, so the bar's rule above (anchored to
-- `^quickshell$` on purpose, to keep the wallpaper layer out) does not reach
-- them. Same treatment for the same reason: the card is translucent, so
-- without blur it shows whatever window it landed on straight through, and a
-- status card over a text editor is unreadable in a way the bar never is.
-- `ignore_alpha` is higher than the bar's 0.2 because there are no fully
-- transparent gaps to protect here, only the rounded corners.
hl.layer_rule({
    name  = "quickshell-osd-blur",
    match = { namespace = "^qs-(audioosd|brightnessosd|contrastosd|kbosd|launcher|keybinds)$" },

    blur         = true,
    ignore_alpha = 0.2,
})

-- Every popup a bar pill opens -- audio, mic, network, calendar,
-- notifications, disk, media, the Claude panel, dzuma, settings, the system
-- monitor, the power menu, the toast stack, and BarPopup's own default
-- namespace for anything that does not set its own -- is a `PanelWindow` on
-- its own layer, so neither rule above reaches it: the first is anchored to
-- `^quickshell$` (the bar itself), the second to the four OSDs. The
-- wallpaper switcher (`qs-wallpapers`) gets the same treatment, since it is
-- chrome floating over the desktop the same as any other popup. `qs-wallpaper`
-- (singular) is deliberately left out of the list -- that is the wallpaper
-- layer itself, and blurring it would blur the background into itself, hence
-- the anchored alternation rather than a `qs-wallpaper` prefix that would
-- catch both. Same `ignore_alpha` as the OSDs: these cards have no fully
-- transparent gaps to protect, only rounded corners.
hl.layer_rule({
    name  = "quickshell-popup-blur",
    match = { namespace = "^qs-(audio|calendar|claude|disk|dzuma|edge|media|mic|network|notifications|popup|popups|power|settings|sysmon|wallpapers)$" },

    blur         = true,
    ignore_alpha = 0.2,
})

-- The desktop layer (giant clock + now-playing card, DesktopWidgets.qml,
-- namespace qs-desktop) deliberately gets NO blur rule: the card is meant to
-- be see-through, and a blurred backdrop turns its low-alpha body into a
-- solid-looking frosted slab that hides the wallpaper it sits on.

-- Layer rules also return a handle.
