-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

-- Spotify always opens on the second monitor's third workspace, whether it was
-- started by CTRL+ALT+S, from a launcher or at boot. "silent" keeps the boot-time
-- launch from dragging focus away; the bind focuses the workspace itself.
hl.window_rule({
    name  = "spotify-workspace",
    match = { class = "^spotify$" },

    workspace = SPOTIFY_WS .. " silent",
})

-- Vesktop is started at launch (see the exec_cmd block at the top) and lands on
-- the second monitor's first workspace. "silent" so the boot-time launch does
-- not drag focus off the main monitor.
hl.window_rule({
    name  = "vesktop-workspace",
    match = { class = "^vesktop$" },

    workspace = VESKTOP_WS .. " silent",
})

-- Signal, same deal: pinned to the second monitor's second workspace and silent
-- so the boot-time launch stays out of the way.
hl.window_rule({
    name  = "signal-workspace",
    match = { class = "^org.signal.Signal$" },

    workspace = SIGNAL_WS .. " silent",
})

